inputs = ['ek', 'kbivwy', 'hfxwvi', 'kykxk', 'cbw']
outputs = ['exxu', 'xxudidivwfud', 'jyjfxwvi', 'xxufudxxuxxxu', 'cdidw']

# Let's look at each pair individually
for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"\nPair {i}: '{inp}' -> '{outp}'")

    # Find where they differ
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    if len(inp) != len(outp):
        if len(inp) > len(outp):
            for j in range(min_len, len(inp)):
                diff_positions.append((j, inp[j], None))
        else:
            for j in range(min_len, len(outp)):
                diff_positions.append((j, None, outp[j]))

    print(f"  Differences at positions: {diff_positions}")

